21.2 Sensitivity 1: minimum total sample size (N ≥ 40)
Restricts to contrasts where \(n_1 + n_2 \geq 40\). Checks whether conclusions about the priority moderators change when poorly replicated contrasts are excluded.


Code
dat_n40 &lt;- dat_es |&gt; dplyr::filter(n_total &gt;= 40)
cat("Contrasts with N &gt;= 40:", nrow(dat_n40), "\n")

sens1_results &lt;- list()
for (moderator in priority_mods) {
  if (!moderator %in% names(dat_n40)) next

  dat_mod &lt;- dat_n40[!is.na(dat_n40[[moderator]]), ]
  if (nrow(dat_mod) &lt; 10) {
    message("Skipping N40 sensitivity for ", moderator, ": too few rows.")
    next
  }

  dat_mod &lt;- dat_mod |&gt;
    dplyr::mutate(es_id_model = factor(seq_len(dplyr::n())))
  if (is.factor(dat_mod[[moderator]])) {
    dat_mod[[moderator]] &lt;- droplevels(dat_mod[[moderator]])
  }

  phylo     &lt;- prepare_phylo_and_data(dat_mod, A_full,
                                      label = paste0("sens1_n40_", moderator))
  dat_mod   &lt;- phylo$dat_model
  A_mod     &lt;- phylo$A_mod
  V         &lt;- phylo$V
  has_phylo &lt;- phylo$has_phylo

  formula &lt;- build_ls_formula(moderator, has_phylogeny = has_phylo)
  priors  &lt;- build_ls_priors(formula, dat_mod, V, A = A_mod)
  mname   &lt;- paste0("sens1_n40_", moderator)

  if (!verify_esid_prior(priors, model_name = mname)) {
    message("Skipping ", mname, ": prior check failed.")
    next
  }

  fit &lt;- tryCatch(
    fit_or_read_model(
      model_name = mname,
      fit_fun    = function() fit_ls_model(dat_mod, formula, priors,
                                           V = V, A = A_mod,
                                           mcmc_args = default_mcmc_args),
      model_dir  = here::here("outputs", "models", "sensitivity"),
      refit      = refit_sensitivity
    ),
    error = function(e) { message("Failed: ", mname); NULL }
  )

  if (!is.null(fit)) {
    sens1_results[[moderator]] &lt;- list(
      fe   = extract_fixed_effects(fit, mname, moderator),
      diag = tryCatch(extract_diagnostics(fit, mname, moderator),
                      error = function(e) NULL)
    )
  }
}



