22.1 Generate figures per moderator
This chapter reads cached model results and generates publication-ready figures. No models are fitted here.
Code
for (i in seq_len(nrow(moderator_grid))) {
  row       &lt;- moderator_grid[i, ]
  mod_id    &lt;- row$model_id
  moderator &lt;- row$moderator
  label     &lt;- row$label
  mod_type  &lt;- row$type

  if (!mod_id %in% fitted_ids) {
    message("Skipping figure for ", mod_id, " (not fitted).")
    next
  }

  loc_dat &lt;- if (!is.null(loc_effects))
    dplyr::filter(loc_effects, model_id == mod_id) else NULL
  scl_dat &lt;- if (!is.null(scl_effects))
    dplyr::filter(scl_effects, model_id == mod_id) else NULL

  if (is.null(loc_dat) || nrow(loc_dat) == 0) {
    message("No location effects for ", mod_id)
    next
  }

  # Build plots based on moderator type
  if (mod_type == "categorical") {
    p_loc &lt;- plot_categorical_location(
      loc_dat |&gt; dplyr::filter(submodel == "location"),
      label
    )
    p_scl &lt;- if (!is.null(scl_dat) && nrow(scl_dat) &gt; 0) {
      plot_categorical_scale(
        scl_dat |&gt; dplyr::filter(submodel == "scale"),
        label
      )
    } else NULL
  } else {
    # For continuous predictors, build a simple coefficient plot
    # (full prediction ribbons require the fitted model object)
    p_loc &lt;- loc_dat |&gt;
      dplyr::filter(submodel == "location", !grepl("^Intercept", term)) |&gt;
      ggplot2::ggplot(ggplot2::aes(x = estimate, y = term)) +
      ggplot2::geom_vline(xintercept = 0, linetype = "dashed", colour = "grey60") +
      ggplot2::geom_pointrange(
        ggplot2::aes(xmin = q2_5, xmax = q97_5), size = 0.6
      ) +
      ggplot2::labs(
        x = "Slope estimate (lnM per unit moderator)",
        y = NULL,
        title = paste("Location slope:", label)
      ) +
      ggplot2::theme_classic(base_size = 12)

    p_scl &lt;- if (!is.null(scl_dat) && nrow(scl_dat) &gt; 0) {
      scl_dat |&gt;
        dplyr::filter(submodel == "scale", !grepl("^Intercept", term)) |&gt;
        ggplot2::ggplot(ggplot2::aes(x = estimate, y = term)) +
        ggplot2::geom_vline(xintercept = 0, linetype = "dashed", colour = "grey60") +
        ggplot2::geom_pointrange(
          ggplot2::aes(xmin = q2_5, xmax = q97_5),
          size = 0.6, colour = "#e06c75"
        ) +
        ggplot2::labs(
          x = "Slope estimate (log sigma per unit moderator)",
          y = NULL,
          title = paste("Scale slope:", label),
          caption = "Positive = greater residual heterogeneity."
        ) +
        ggplot2::theme_classic(base_size = 12)
    } else NULL
  }

  # Save location figure
  fname_loc &lt;- paste0(mod_id, "_", moderator, "_location")
  save_plot_dual(p_loc, fname_loc)

  # Save scale figure
  if (!is.null(p_scl)) {
    fname_scl &lt;- paste0(mod_id, "_", moderator, "_scale")
    save_plot_dual(p_scl, fname_scl, height = 100)

    # Combined figure
    p_combined &lt;- patchwork::wrap_plots(p_loc, p_scl, ncol = 1)
    fname_comb &lt;- paste0(mod_id, "_", moderator, "_location_scale_combined")
    save_plot_dual(p_combined, fname_comb, height = 220)
  }

  message("Saved figures for ", mod_id, " (", moderator, ")")
}

